public sealed class Account {
    public decimal Balance { get; private set; }       // state read-only to clients
    public void Debit(decimal amount) {                 // behaviour owns the invariant
        if (amount <= 0 || amount > Balance) throw new InvalidOperationException();
        Balance -= amount;
    }
}
public static class AccountExtensions {                 // only when you do not own the type
    public static bool IsOverdrawn(this Account a) => a.Balance < 0;
}
